    return;
  }
  const beam: Projectile = {
    uid: world.nextId(),
    owner: owner.uid,
    enemy: state.master === 'enemy',
    x: origin.x,
    y: origin.y,
    angle: owner.rotation + gun.angle,
    heading: owner.rotation + gun.angle,
    speed: 0,
    damage: 1,
    radius: 0,
    age: 0,
    life: Infinity,
    kind: 'healBeam',
    explode: 0,
    targetId: patient.uid,
    healingTarget: patient,
    healingHome: owner,
    hit: new Set(),
    dead: false,
    anchor: gun,
    symbol: 2015,
    artScale: 1,
    orbit: 0,
    contactFrames: 0,
    beamLength: 0,
